using System.IO;
using System.Linq;
using TheLastMemory;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public static class CreateLevelTwoDotCircuit
{
    const string ScenePath="Assets/Scenes/Level2_DotCircuit.unity", MatPath="Assets/Art/Materials";
    [MenuItem("The Last Memory/Level 2/Create Dot Circuit")]
    static void BuildFromMenu()
    {
        if(EditorApplication.isPlaying){EditorApplication.isPlaying=false;EditorApplication.delayCall+=BuildFromMenu;return;}
        if(File.Exists(ScenePath)){EditorUtility.DisplayDialog("Level 2 already exists","Level2_DotCircuit is already in the project. I left it intact.","OK");return;}
        Build();EditorUtility.DisplayDialog("Level 2 created","Dot Circuit is ready. Level 1 leads to it, and completing it loads Neon Courier in Level 3.","OK");
    }
    public static void BuildBatch() { if(!File.Exists(ScenePath)) Build(); }
    static void Build()
    {
        Ensure("Assets/Scenes");Ensure("Assets/Art");Ensure(MatPath);AssetDatabase.Refresh();
        Scene scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
        Material floor=Mat("L2_CircuitFloor",new Color32(8,20,30,255),new Color(.01f,.06f,.1f));
        Material trim=Mat("L2_MetalTrim",new Color32(27,45,58,255));Material cyan=Mat("L2_CyanCircuit",new Color32(10,150,172,255),new Color(.02f,.75f,1));Material amber=Mat("L2_AmberDecoy",new Color32(136,70,24,255),new Color(1,.22f,.015f));Material off=Mat("L2_DormantNode",new Color32(13,51,63,255),new Color(.015f,.16f,.22f));
        GameObject world=new GameObject("Level2_DotCircuit_World");Make("Circuit Platform",PrimitiveType.Cube,world.transform,new Vector3(0,-.38f,18),new Vector3(20,.75f,48),floor,true);Make("Left Edge Light",PrimitiveType.Cube,world.transform,new Vector3(-9.65f,.04f,18),new Vector3(.12f,.08f,46),cyan,false);Make("Right Edge Light",PrimitiveType.Cube,world.transform,new Vector3(9.65f,.04f,18),new Vector3(.12f,.08f,46),cyan,false);Make("Start Deck",PrimitiveType.Cube,world.transform,new Vector3(0,-.02f,0),new Vector3(5,.12f,4),trim,false);
        Texture2D city=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Art/Level2_CyberCity.jpeg");if(city!=null){Material bg=new Material(Shader.Find("Universal Render Pipeline/Unlit"));if(bg.HasProperty("_BaseMap"))bg.SetTexture("_BaseMap",city);if(bg.HasProperty("_MainTex"))bg.SetTexture("_MainTex",city);AssetDatabase.CreateAsset(bg,MatPath+"/L2_CyberCityBackdrop.mat");GameObject quad=Make("Cyber City Backdrop",PrimitiveType.Quad,world.transform,new Vector3(0,25,53),new Vector3(64,114,1),bg,false);quad.transform.rotation=Quaternion.Euler(0,180,0);}
        GameObject player=new GameObject("PlayerController");player.transform.position=Vector3.up;player.AddComponent<CharacterController>();PlayerController pc=player.AddComponent<PlayerController>();GameObject capsule=GameObject.CreatePrimitive(PrimitiveType.Capsule);capsule.name="Capsule";capsule.transform.SetParent(player.transform,false);Object.DestroyImmediate(capsule.GetComponent<Collider>());SerializedObject pso=new SerializedObject(pc);pso.FindProperty("playerVisual").objectReferenceValue=capsule.transform;pso.FindProperty("moveSpeed").floatValue=4;pso.ApplyModifiedPropertiesWithoutUndo();
        GameObject camObj=new GameObject("Main Camera");camObj.tag="MainCamera";Camera cam=camObj.AddComponent<Camera>();cam.fieldOfView=70;cam.farClipPlane=180;camObj.AddComponent<AudioListener>();SerializedObject cso=new SerializedObject(pc);cso.FindProperty("cameraPivot").objectReferenceValue=camObj.transform;cso.ApplyModifiedPropertiesWithoutUndo();
        Light sun=new GameObject("Cool City Key Light").AddComponent<Light>();sun.type=LightType.Directional;sun.color=new Color32(127,172,200,255);sun.intensity=.62f;sun.transform.rotation=Quaternion.Euler(37,-30,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color32(30,42,55,255);RenderSettings.fog=true;RenderSettings.fogColor=new Color32(28,37,48,255);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.004f;
        Vector3[] pts={new Vector3(0,.17f,5),new Vector3(-3.5f,.17f,10),new Vector3(2.5f,.17f,15),new Vector3(-3.5f,.17f,20),new Vector3(2.5f,.17f,25),new Vector3(0,.17f,30)};Transform[] nodes=new Transform[pts.Length];for(int i=0;i<pts.Length;i++){GameObject n=Make("Circuit Node "+(i+1),PrimitiveType.Cylinder,world.transform,pts[i],new Vector3(1.25f,.1f,1.25f),off,false);nodes[i]=n.transform;Label(world.transform,(i+1).ToString("00"),pts[i]+Vector3.up*.45f);if(i>0)Line(world.transform,pts[i-1]+Vector3.up*.02f,pts[i]+Vector3.up*.02f,cyan);}
        Vector3[] wrong={new Vector3(5.5f,.17f,10),new Vector3(-7.2f,.17f,15),new Vector3(5.5f,.17f,20),new Vector3(-7.2f,.17f,25)};Transform[] decoys=new Transform[wrong.Length];for(int i=0;i<wrong.Length;i++){GameObject n=Make("Broken Branch "+(i+1),PrimitiveType.Cylinder,world.transform,wrong[i],new Vector3(1.1f,.08f,1.1f),amber,false);decoys[i]=n.transform;Line(world.transform,pts[Mathf.Min(i+1,pts.Length-1)]+Vector3.up*.025f,wrong[i]+Vector3.up*.025f,amber);}
        GameObject goal=Make("Circuit Receiver",PrimitiveType.Cylinder,world.transform,new Vector3(0,.17f,34),new Vector3(2.5f,.14f,2.5f),cyan,false);Label(world.transform,"END",goal.transform.position+Vector3.up*.35f);
        Text status,progress,timer;BuildHud(out status,out progress,out timer);DotCircuitPuzzle puzzle=new GameObject("Dot Circuit Puzzle").AddComponent<DotCircuitPuzzle>();puzzle.Configure(player.transform,nodes,decoys,status,progress,timer);
        AudioSource ambience=new GameObject("Level2Ambience").AddComponent<AudioSource>();ambience.loop=true;ambience.playOnAwake=false;ambience.spatialBlend=0;ambience.volume=.35f;ambience.clip=FindFear();if(ambience.clip!=null)ambience.Play();
        EditorSceneManager.SaveScene(scene,ScenePath);AddBuild("Assets/Scenes/SampleScene.unity");AddBuild(ScenePath);AddBuild("Assets/Scenes/Level3_NeonCourier.unity");Selection.activeGameObject=player;
    }
    static AudioClip FindFear(){foreach(string guid in AssetDatabase.FindAssets("t:AudioClip",new[]{"Assets"})){string p=AssetDatabase.GUIDToAssetPath(guid);string n=Path.GetFileNameWithoutExtension(p).Replace("_","-").Replace(" ","-");if(n.Equals("freshmansound-fear",System.StringComparison.OrdinalIgnoreCase))return AssetDatabase.LoadAssetAtPath<AudioClip>(p);}return null;}
    static void BuildHud(out Text status,out Text progress,out Text timer){GameObject cv=new GameObject("Level2 HUD",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));Canvas c=cv.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;CanvasScaler sc=cv.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);sc.matchWidthOrHeight=.5f;GameObject panel=new GameObject("Circuit Status Panel",typeof(RectTransform),typeof(Image));panel.transform.SetParent(cv.transform,false);RectTransform r=panel.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(28,-28);r.sizeDelta=new Vector2(600,205);panel.GetComponent<Image>().color=new Color(.015f,.035f,.055f,.88f);Text h=TextAt(panel.transform,"LEVEL 2 — DOT CIRCUIT",new Vector2(20,-14),new Vector2(560,32),22,new Color(.3f,.93f,1));h.fontStyle=FontStyle.Bold;status=TextAt(panel.transform,"",new Vector2(20,-52),new Vector2(560,90),16,Color.white);progress=TextAt(panel.transform,"NODES 0/6 | ERRORS 0/2",new Vector2(20,-154),new Vector2(370,28),15,new Color(.72f,.88f,.92f));timer=TextAt(panel.transform,"TIME 60s",new Vector2(410,-154),new Vector2(170,28),15,new Color(1,.73f,.35f));}
    static Text TextAt(Transform p,string v,Vector2 pos,Vector2 size,int fs,Color color){GameObject g=new GameObject("HUD Text",typeof(RectTransform),typeof(Text));g.transform.SetParent(p,false);RectTransform r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=size;Text t=g.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=v;t.fontSize=fs;t.color=color;t.alignment=TextAnchor.MiddleLeft;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}
    static GameObject Make(string name,PrimitiveType type,Transform parent,Vector3 pos,Vector3 scale,Material m,bool collider){GameObject g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,true);g.transform.SetPositionAndRotation(pos,Quaternion.identity);g.transform.localScale=scale;Renderer r=g.GetComponent<Renderer>();if(r)r.sharedMaterial=m;if(!collider){Collider c=g.GetComponent<Collider>();if(c)Object.DestroyImmediate(c);}return g;}
    static void Label(Transform parent,string text,Vector3 pos){GameObject g=new GameObject("Node label "+text,typeof(TextMesh));g.transform.SetParent(parent,true);g.transform.position=pos;g.transform.rotation=Quaternion.Euler(90,0,0);TextMesh t=g.GetComponent<TextMesh>();t.text=text;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.characterSize=.5f;t.fontSize=48;t.color=new Color(.75f,1,1);}
    static void Line(Transform p,Vector3 a,Vector3 b,Material m){GameObject g=new GameObject("Circuit Trace");g.transform.SetParent(p,false);LineRenderer l=g.AddComponent<LineRenderer>();l.useWorldSpace=true;l.positionCount=2;l.SetPosition(0,a);l.SetPosition(1,b);l.startWidth=l.endWidth=.09f;l.sharedMaterial=m;l.startColor=l.endColor=m.color;l.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;l.receiveShadows=false;}
    static Material Mat(string name,Color c,Color? emission=null){string p=MatPath+"/"+name+".mat";Material m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){Shader s=Shader.Find("Universal Render Pipeline/Lit");if(s==null)s=Shader.Find("Standard");m=new Material(s);AssetDatabase.CreateAsset(m,p);}m.color=c;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);if(emission.HasValue){m.EnableKeyword("_EMISSION");if(m.HasProperty("_EmissionColor"))m.SetColor("_EmissionColor",emission.Value*2);}EditorUtility.SetDirty(m);return m;}
    static void Ensure(string path){if(AssetDatabase.IsValidFolder(path))return;string p=Path.GetDirectoryName(path)?.Replace('\\','/');if(!AssetDatabase.IsValidFolder(p))Ensure(p);AssetDatabase.CreateFolder(p,Path.GetFileName(path));}
    static void AddBuild(string p){if(!File.Exists(p))return;var s=EditorBuildSettings.scenes;if(!s.Any(x=>x.path==p))EditorBuildSettings.scenes=s.Concat(new[]{new EditorBuildSettingsScene(p,true)}).ToArray();}
}
